CONTROL_PLANE_SCRIPT = """
const legacyRenderDashboard=renderDashboard;
renderDashboard=function(data){legacyRenderDashboard(data);renderControlPlane(data);};
const controlPlaneCopy={core_web:'可用于公开网页发现与资料提取。',academic:'可补充学术元数据与开放资料线索。',video_media:'可按需理解图片、视频与文本材料。',login_platforms:'首次实际使用时，需要在自己的浏览器完成登录。',browser:'按需下载，用于动态网页与受支持浏览器流程。',xhs_bridge:'仅用于小红书本地 bridge 诊断。'};
const toolLabel={kr_research:'发起研究',kr_web_search:'网页检索',search_academic:'学术检索',search_youtube:'视频检索',search_bilibili:'B 站检索',get_content_detail:'内容详情'};
function capabilityView(item){return item.id==='browser'||item.id==='xhs_bridge'?'components':'services';}
function capabilityAction(item){if(item.state==='connected'||item.state==='local_ready')return '查看能力';if(item.state==='manual')return '了解登录方式';return item.id==='browser'||item.id==='xhs_bridge'?'管理组件':'去配置';}
function renderControlPlane(data){const plane=data.control_plane||{capabilities:[],connected_count:0,attention_count:0};const capabilities=plane.capabilities||[];const connected=Number(plane.connected_count||0);const attention=Number(plane.attention_count||0);const ready=data.research_readiness==='ready';const tasks=data.activity?.tasks||{};const tools=data.activity?.tools||{};const installation=data.installation||{};const topTools=(tools.top_tools||[]).map(item=>`${toolLabel[item.label]||item.label} ${item.count}`).join(' · ');$('#cp-snapshot').textContent=`${data.window?.label||'近 7 天'} · 本机状态快照`;$('#cp-status-label').textContent=ready?'核心研究已接入':'核心研究待配置';$('#cp-readiness-title').textContent=ready?'可以开始研究':'还差一步即可开始研究';$('#cp-readiness-detail').textContent=ready?'核心网页研究所需的本机配置已存在。你可以直接在 Codex 发起研究，或继续按需扩展能力。':'先在能力中心配置一个网页搜索来源；完成后即可发起公开网页研究。';$('#cp-connected-count').textContent=String(connected);$('#cp-connected-label').textContent=`项能力已接入 · 共 ${capabilities.length} 项`;$('#cp-mission-action').textContent=tasks.available?(tasks.active?`当前有 ${tasks.active} 项任务正在处理。`:'当前没有正在运行的研究任务。'):'尚未发现本机任务记录。';$('#cp-attention-count').textContent=attention?`${attention} 项待处理`:'无需处理';const attentionRows=capabilities.filter(item=>!['connected','local_ready'].includes(item.state));$('#cp-attention-list').innerHTML=attentionRows.length?attentionRows.map(item=>`<article class="attention-item ${escapeHtml(item.state)}"><i class="attention-dot"></i><div class="attention-copy"><strong>${escapeHtml(item.label)}</strong><span>${escapeHtml(item.detail)}</span></div><button data-go-to="${capabilityView(item)}">${capabilityAction(item)}</button></article>`).join(''):'<div class="attention-empty">当前没有待处理的能力项</div>';$('#cp-capability-summary').textContent=`${connected} 项已接入 · ${attention} 项可按需处理`;$('#cp-capability-grid').innerHTML=capabilities.map(item=>`<article class="capability-card ${escapeHtml(item.state)}"><div class="capability-top"><i class="capability-mark">${escapeHtml(item.label.slice(0,1))}</i><span class="capability-state ${escapeHtml(item.state)}">${escapeHtml(item.detail)}</span></div><div><h4>${escapeHtml(item.label)}</h4><p>${escapeHtml(controlPlaneCopy[item.id]||'该能力的状态仅根据本机配置或组件记录显示。')}</p></div><button data-go-to="${capabilityView(item)}">${capabilityAction(item)} →</button></article>`).join('');$('#cp-active').textContent=tasks.available?String(tasks.active||0):'—';$('#cp-active-note').textContent=tasks.available?(tasks.active?'任务正在本机队列中处理。':'当前队列为空。'):'尚无任务记录。';$('#cp-tools').textContent=tools.available?String(tools.successful||0):'—';$('#cp-tools-note').textContent=tools.available?(topTools?`常用：${topTools}`:'已有运行记录，暂未形成常用功能聚合。'):'尚无工具调用记录。';$('#cp-install-version').textContent=installation.available?String(installation.version||'—'):'未识别';$('#cp-install-note').textContent=installation.available?`${installation.channel||'unknown'} · ${installation.data_root_present?'数据根可用':'数据根待检查'}${installation.rollback_available?' · 可回退':''}`:String(installation.message||'安装状态尚不可用');bindGoTo();}
$('#cp-refresh').onclick=refreshDashboard;
$('.topbar p').textContent='能力、任务与本机运行态。';
refreshDashboard();
"""
